import numpy as np


def mi_split_heads(x, n_heads):
    x = np.asarray(x, dtype=float)
    T, d = x.shape
    return x.reshape(T, d // n_heads, n_heads).transpose(2, 0, 1)

import numpy as np


def mi_split_heads(x, n_heads):
